-- App-owned schema. All private mutations serialize on app_users, after session
-- validation. Auth tables above remain generated by the pinned library.
CREATE UNIQUE INDEX account_provider_subject_unique ON "account" ("providerId", "accountId");

CREATE TABLE app_users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  auth_user_id text NOT NULL UNIQUE REFERENCES "user"(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'deleting')),
  profile_revision bigint NOT NULL DEFAULT 0 CHECK (profile_revision >= 0),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE user_settings (
  user_id uuid PRIMARY KEY REFERENCES app_users(id) ON DELETE CASCADE,
  revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
  shelf_revision bigint NOT NULL DEFAULT 0 CHECK (shelf_revision >= 0),
  history_generation bigint NOT NULL DEFAULT 0 CHECK (history_generation >= 0),
  history_enabled boolean NOT NULL DEFAULT false
);
CREATE TABLE user_libraries (
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  directory_id text NOT NULL CHECK (length(directory_id) BETWEEN 1 AND 200),
  selected boolean NOT NULL DEFAULT true,
  PRIMARY KEY (user_id, directory_id)
);
CREATE UNIQUE INDEX one_selected_library ON user_libraries(user_id) WHERE selected;
CREATE TABLE book_refs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  book_key text NOT NULL CHECK (length(book_key) BETWEEN 1 AND 4096),
  key_digest bytea NOT NULL UNIQUE CHECK (octet_length(key_digest) = 32),
  provider_metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE user_books (
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  reference_id uuid NOT NULL REFERENCES book_refs(id),
  saved_at timestamptz NOT NULL DEFAULT now(),
  display_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (user_id, reference_id)
);
CREATE INDEX saved_book_page ON user_books(user_id, saved_at DESC, reference_id DESC);
CREATE TABLE recent_book_views (
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  reference_id uuid NOT NULL REFERENCES book_refs(id),
  viewed_at timestamptz NOT NULL,
  display_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (user_id, reference_id)
);
CREATE INDEX recent_book_page ON recent_book_views(user_id, viewed_at DESC, reference_id DESC);
CREATE TABLE guest_imports (
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  import_id uuid NOT NULL,
  payload_hash bytea NOT NULL CHECK (octet_length(payload_hash) = 32),
  result jsonb NOT NULL,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '30 days',
  PRIMARY KEY (user_id, import_id)
);
CREATE TABLE account_operations (
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  operation_id uuid NOT NULL,
  payload_hash bytea NOT NULL CHECK (octet_length(payload_hash) = 32),
  result jsonb NOT NULL,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  PRIMARY KEY (user_id, operation_id)
);

-- FORCE also protects a table owner unless it has BYPASSRLS/superuser. Runtime
-- roles are separately checked at startup and must have neither capability.
DO $$
DECLARE target text;
BEGIN
  FOREACH target IN ARRAY ARRAY['app_users','user_settings','user_libraries','user_books','recent_book_views','guest_imports','account_operations'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', target);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', target);
    EXECUTE format('CREATE POLICY owned_rows ON %I USING (%I = nullif(current_setting(''mybookshelf.user_id'', true), '''')::uuid) WITH CHECK (%I = nullif(current_setting(''mybookshelf.user_id'', true), '''')::uuid)',
      target, CASE WHEN target = 'app_users' THEN 'id' ELSE 'user_id' END,
      CASE WHEN target = 'app_users' THEN 'id' ELSE 'user_id' END);
  END LOOP;
END $$;
